  const row = page.getByRole("listitem").first();
  await expect(row).toHaveCSS("animation-name", "none");
  await page.getByRole("link", { name: "Companies", exact: true }).click();
  await expect(page.getByRole("listitem").first()).toHaveCSS(
    "animation-name",
    "none",
  );
});

